int Empty(Stack &s1,Stack &s2)
{
if(s1.empty()&&s2.empty())
return 1;
else return 0;
}
void POP(stack &s1,stack &s2,elemtype &x)
{
if(!empty(s2))
{
pop(s2,x);
}
else if(!empty(s1))
{
cout<<"队列为空"<<endl;
}
else{
while(!empty(s1))
{
pop(s1,x);
push(s2,x);
}
pop(s2,x);
}
}
int PUSH(stack &s1,stack &s2,elemtype x)
{
if(!overflow(s1))
{
push(s1,x);
return 1;
}
if(overflow(s1)&&!empty(s2))
{
cout<<"满"<<endl;
return 0;
}
if(overflow(s1)&&empty(s2))
{
while(!empty(s1))
{
pop(s1,x);
push(s2,x);
}
push(s1,x);
return 1;
}
}
